fn frame(t: i32) {
    let px: i32 = host::display::pointer_x();
    let py: i32 = host::display::pointer_y();
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(1);
    let mx: i32 = 60;
    let my: i32 = 80;
    let mw: i32 = 200;
    let ih: i32 = 36;
    let mut hover: i32 = -1;
    if px >= mx && px < mx + mw && py >= my && py < my + ih * 4 {
        hover = (py - my) / ih;
    }
    let mut sel: i32 = host::display::state_get(0);
    if down == 1 && prev == 0 && hover >= 0 {
        sel = hover;
        host::display::state_set(0, sel);
    }
    host::display::state_set(1, down);
    host::display::clear(0x101014);
    host::display::draw_string(mx, 50, "MAIN MENU", 0x808080, 2);
    let mut i: i32 = 0;
    while i < 4 {
        let y: i32 = my + i * ih;
        let mut bgc: i32 = 0x181820;
        if i == hover { bgc = 0x303048; }
        host::display::fill_rect(mx, y, mw, ih - 2, bgc);
        if i == sel {
            host::display::fill_rect(mx + 4, y + ih / 2 - 5, 8, 8, 0x00ff88);
        }
        i = i + 1;
    }
    host::display::draw_string(mx + 20, my + 14, "NEW GAME", 0xffffff, 1);
    host::display::draw_string(mx + 20, my + ih + 14, "CONTINUE", 0xffffff, 1);
    host::display::draw_string(mx + 20, my + ih * 2 + 14, "OPTIONS", 0xffffff, 1);
    host::display::draw_string(mx + 20, my + ih * 3 + 14, "QUIT", 0xffffff, 1);
    host::display::present();
}
